var addBrowserMenuLinks,
  addBrowserMenuLinks = function() {
    chrome.contextMenus.create({
      id: 'settings',
      title: 'Account Settings',
      contexts: ['action']
    });
    return chrome.contextMenus.create({
      id: 'upgrade',
      title: 'Upgrade',
      contexts: ['action']
    });
  };
addBrowserMenuLinks();

chrome.contextMenus.onClicked.addListener(function(info, tab) {
  switch (info.menuItemId) {
    case 'settings':
      chrome.tabs.create({
        url: 'https://v1.tldrthis.com/settings?utm_source=chrome_extension'
      });
      break;
    case 'upgrade':
      chrome.tabs.create({
        url:
          'https://v1.tldrthis.com/subscription/billing?utm_source=chrome_extension'
      });
      break;
  }
});

// install url
chrome.runtime.onInstalled.addListener(function(object) {
  if (object.reason === 'install') {
    chrome.tabs.create({
      url: 'https://v1.tldrthis.com/chrome/welcome?utm_source=chrome_extension'
    });
  }
});

// uninstall url
chrome.runtime.setUninstallURL(
  'https://v1.tldrthis.com/chrome/uninstall?utm_source=chrome_extension'
);
